#!/bin/bash
# config_module.sh - stage 2 of the build of [MODULE_NAME]: the build plan (run by build.sh, the stage runner)
# Generated by LLM Cross-Compiler Framework
#
# Image:  this target's Dockerfile (base image debian:bookworm-slim) for the build host's architecture.
# Target: [MODULE_NAME] ([IHRE_ARCHITEKTUR] Linux).
# Stage:  reads the request from the environment, normalizes it (lower-case format and board, the GGUF type names and
#         their aliases) and refuses what this target cannot build before anything slow runs; then writes the build
#         plan, build_config.sh in the stage folder, which the convert and target stages read.
#         With a hardware profile of the board (HARDWARE_CONFIG_FILE, or $BUILD_CACHE_DIR/target_hardware_config.txt)
#         it also generates the CMake toolchain from it, with the CPU and CMake flags of the module wizard: the
#         target stage then packages llama-cli and llama-server for the board (version 1.x). The BuildEngine hands
#         the board's stored probe to every build (read-only, HARDWARE_CONFIG_FILE=/build-cache/hardware/...; DECISIONS
#         round 23 item 5) when there is one; an x86_64 board's CPU is then planned as the build recipe plans it
#         (plan_x86_cpu: -march=native only for this build machine, else the probe's own features).
#         The compilers are CC and CXX of the image (default cc and c++; a module that cross-compiles sets them in its
#         Dockerfile, e.g. ENV CC=aarch64-linux-gnu-gcc CXX=aarch64-linux-gnu-g++), looked up where the shell finds
#         them and named in the toolchain file; a profile of another system than [IHRE_ARCHITEKTUR] is refused.
# Validation (version 1.x: "Professional Validation - compiler tests, syntax checks"): before the plan is used, the
#         compilers build and link a small C and C++ program with the module's flags (the programs must be ELF
#         programs for [IHRE_ARCHITEKTUR]), CMake reads the generated toolchain file, and build_config.sh must be a
#         valid shell script that sets every name the later stages read. A plan that fails a check is never written.
#         The target stage checks the same way when it plans a package without a profile (plan_board defaults: the
#         module's own flags, no probe features).
# SECURITY: the flags are written with quoted heredocs and single quotes, never expanded by the shell.
#
# Inputs (environment, set by BuildEngine):
#   MODEL_SOURCE   local HF model directory inside the container (staged by the host), or a GGUF file (quantized by
#                  the target stage, nothing converted)
#   TARGET_FORMAT  gguf                                       (default: gguf)
#   TARGET_BOARD   board id from target.yml                   (optional)
#   QUANTIZATION   e.g. Q4_K_M, IQ4_XS, Q8_0, F16
#   JOB_TYPE       build | imatrix
#   USE_IMATRIX / IMATRIX_PATH, DATASET_PATH, MODEL_NAME, MODEL_TASK, MODEL_REVISION (optional)
# The image sets LLAMA_CPP_PATH; the BuildEngine mounts $BUILD_CACHE_DIR/output (results) and $BUILD_SCRATCH_DIR (the
# work folder for intermediates, never /tmp: a small tmpfs in the build sandbox).

set -euo pipefail

# Environment & Paths
BUILD_CACHE_DIR="${BUILD_CACHE_DIR:-/build-cache}"
WORK_DIR="$BUILD_CACHE_DIR"
OUTPUT_DIR="${WORK_DIR}/output"
IMATRIX_DIR="${WORK_DIR}/imatrix"
# Large intermediates (F16 GGUF) go to the mounted work folder; the image filesystem may be read-only.
SCRATCH_DIR="${BUILD_SCRATCH_DIR:-$WORK_DIR}"
PLAN_DIR="${STAGE_DIR:-$SCRATCH_DIR}"
BUILD_PLAN="$PLAN_DIR/build_config.sh"
CMAKE_TOOLCHAIN="$PLAN_DIR/cross_compile_toolchain.cmake"

LLAMA_BASE="${LLAMA_CPP_PATH:-/usr/src/llama.cpp}"
CONVERT_SCRIPT="$LLAMA_BASE/convert_hf_to_gguf.py"
QUANTIZE_BIN="$LLAMA_BASE/build/bin/llama-quantize"
IMATRIX_BIN="$LLAMA_BASE/build/bin/llama-imatrix"

# The hardware profile of the board (KEY=VALUE lines of scripts/hardware_probe.sh), when one is given
declare -A HW_CONFIG
# The compilers and flags of the board's part of the plan
declare -A COMPILER_CONFIG
# Where the board's part of the plan comes from: profile (a hardware profile) or defaults (no profile)
PROFILE_SOURCE=""

die() { echo "ERROR: $*" >&2; exit 1; }
log() { echo ">> [Config] $1"; }
log_success() { echo ">> [Config] $1"; }
log_warn() { echo "WARNING: $1" >&2; }
log_info() { log "$1"; }

# --- GGUF types (llama.cpp; the same lists as targets/Rockchip/modules/config_module.sh) ------------------------

# Used by convert_module.sh, which sources this file.
# shellcheck disable=SC2034
{
# Output types convert_hf_to_gguf.py writes directly.
GGUF_CONVERT_TYPES=" f32 f16 bf16 q8_0 auto "
# Every quantization method of llama-quantize at the pin (QUANT_OPTIONS of tools/quantize/quantize.cpp, llama.cpp
# b11429 = v0.6.0), except F16, BF16 and F32, which the converter writes itself, and COPY, which quantizes nothing;
# its aliases Q3_K, Q4_K and Q5_K are accepted by normalize_gguf_type.
GGUF_QUANT_TYPES=" Q4_0 Q4_1 Q5_0 Q5_1 Q8_0 Q2_K Q2_K_S Q3_K_S Q3_K_M Q3_K_L Q4_K_S Q4_K_M Q5_K_S Q5_K_M Q6_K \
IQ1_S IQ1_M IQ2_XXS IQ2_XS IQ2_S IQ2_M IQ3_XXS IQ3_XS IQ3_S IQ3_M IQ4_NL IQ4_XS TQ1_0 TQ2_0 MXFP4_MOE Q1_0 Q2_0 "
# llama-quantize refuses these without an importance matrix: tensors of the file get a type that requires one
# (tensor_requires_imatrix of src/llama-quant.cpp at the pin: IQ1_S, IQ1_M, IQ2_XXS, IQ2_XS, IQ2_S, IQ3_XXS, and Q2_K in
# a Q2_K_S file; IQ2_M is mostly IQ2_S, and IQ3_XS makes attn_q, attn_k and the middle ffn_gate and ffn_up IQ3_XXS).
# The other i-quants lose quality without one.
GGUF_NEEDS_IMATRIX=" IQ1_S IQ1_M IQ2_XXS IQ2_XS IQ2_S IQ2_M IQ3_XXS IQ3_XS Q2_K_S "
GGUF_WANTS_IMATRIX=" IQ3_S IQ3_M IQ4_NL IQ4_XS "
}

normalize_gguf_type() {
    local q
    q="$(echo "$1" | tr '[:lower:]' '[:upper:]')"
    case "$q" in
        ""|F16|FP16) echo "F16" ;;
        BF16) echo "BF16" ;;
        F32|FP32) echo "F32" ;;
        INT8|Q8) echo "Q8_0" ;;
        INT4|Q4|Q4_K) echo "Q4_K_M" ;;
        Q5|Q5_K) echo "Q5_K_M" ;;
        Q3_K) echo "Q3_K_M" ;;
        *) echo "$q" ;;
    esac
}

# --- The request (the checks of the former build.sh dispatcher) ---------------------------------------------------

plan_request() {
    FORMAT="$(echo "${TARGET_FORMAT:-gguf}" | tr '[:upper:]' '[:lower:]')"
    BOARD="$(echo "${TARGET_BOARD:-}" | tr '[:upper:]' '[:lower:]')"
    JOB="${JOB_TYPE:-build}"
    MODEL_SOURCE="${MODEL_SOURCE:-}"
    local requested="${QUANTIZATION:-}" name
    # The input: a model folder for the converter, or a GGUF file, the F16 GGUF that target_module.sh of version 1.x
    # took (the convert stage then converts nothing; the defaults of 1.x: the file name without .gguf and .fp16, and
    # Q4_K_M).
    INPUT_FORMAT="model"
    if [ -f "$MODEL_SOURCE" ] && [[ "$MODEL_SOURCE" == *.[gG][gG][uU][fF] ]]; then
        INPUT_FORMAT="gguf"
        name="$(basename "$MODEL_SOURCE")"
        name="${name%.*}"
        MODEL_NAME="${MODEL_NAME:-${name%.fp16}}"
        if [ -z "$requested" ]; then
            requested="Q4_K_M"
        fi
    else
        MODEL_NAME="${MODEL_NAME:-$(basename "${MODEL_SOURCE%/}")}"
    fi
    QUANT_TYPE="$(normalize_gguf_type "$requested")"

    echo "Model:        $MODEL_SOURCE"
    echo "Task:         ${MODEL_TASK:-LLM}"
    echo "Format:       $FORMAT"
    echo "Board:        ${BOARD:-<default>}"
    echo "Quantization: $QUANT_TYPE"
    echo "Job:          $JOB"

    if [ -z "$MODEL_SOURCE" ] && [ "${STAGE_LAST:-}" = "config" ]; then
        # config_module.sh --hardware-config FILE (version 1.x): the toolchain and the plan of the board only
        echo "No model (--input): the build plan holds the hardware profile only."
    else
        [ -n "$MODEL_SOURCE" ] && [ -e "$MODEL_SOURCE" ] || die "MODEL_SOURCE '$MODEL_SOURCE' does not exist in the container."
    fi

    # The importance-matrix job converts and measures only; its container has no output folder.
    [ "$JOB" = "imatrix" ] && return 0

    case "$FORMAT" in
        gguf) ;;
        *) die "Format '$FORMAT' is not supported by this target (gguf)." ;;
    esac

    mkdir -p "$OUTPUT_DIR"
}

# --- The hardware profile and the CMake toolchain (optional) -------------------------------------------------------

load_hardware_config() {
    log "Loading hardware profile from $HARDWARE_CONFIG_FILE..."
    # SECURITY: only keys of A-Z, 0-9 and _ (no eval, no declare of a name from the file)
    local key value
    while IFS='=' read -r key value; do
        if [[ $key =~ ^[A-Z0-9_]+$ ]]; then
            # Entferne eventuelle Windows CR Zeichen
            HW_CONFIG["$key"]="$(echo "$value" | tr -d '\r')"
        fi
    done < <(grep '=' "$HARDWARE_CONFIG_FILE")
    # The build jobs are capped at the board's cores (CPU_CORES of version 1.x; the probe writes CPU_CORES_LOGICAL).
    HW_CONFIG[CPU_CORES]="${HW_CONFIG[CPU_CORES]:-${HW_CONFIG[CPU_CORES_LOGICAL]:-}}"
    # The profile must be of the system this module builds for (the probe writes ARCH: arm64, x86_64, armv7, ...); a
    # system whose programs are not the module's (elf_machine_of), or one it does not know, is refused.
    local system="${HW_CONFIG[ARCHITECTURE_FULL]:-${HW_CONFIG[ARCH]:-}}"
    if [ -n "$system" ] && [ "$(elf_machine_of "$system")" != "$(elf_machine_of '[IHRE_ARCHITEKTUR]')" ]; then
        die "The hardware profile is of a $system system; this module builds for [IHRE_ARCHITEKTUR], so nothing was planned for it."
    fi
    HW_CONFIG[ARCHITECTURE_FULL]='[IHRE_ARCHITEKTUR]'
    # The CPU model as the x86 plan compares it with this build machine's (profile_is_this_machine)
    HW_CONFIG[CPU_MODEL_NAME]="${HW_CONFIG[CPU_MODEL_NAME]:-${HW_CONFIG[CPU_MODEL]:-}}"
    PROFILE_SOURCE="profile"
}

# Without a hardware profile, a package for the board (build.sh --package; target_module.sh started by hand) is planned
# with the plain defaults of this module: its own flags, no feature of a probe.
load_plain_defaults() {
    HW_CONFIG=([ARCHITECTURE_FULL]='[IHRE_ARCHITEKTUR]')
    PROFILE_SOURCE="defaults"
    log "No hardware profile: the plain defaults of this module ([IHRE_ARCHITEKTUR], the module's flags)"
}

# ============================================================================
# THE CPU OF AN x86_64 PROFILE: -march=native only for this build machine itself
# The same functions in targets/Rockchip and targets/_template (tests/test_target_stage.py compares them). They read
# the profile from HW_CONFIG (ARCHITECTURE_FULL, CPU_MODEL_NAME, the SUPPORTS_* keys) and its file
# (HARDWARE_CONFIG_FILE, for CPU_FLAGS_ALL as written), and set X86_CFLAGS and X86_CMAKE_FLAGS.
# ============================================================================

# The x86 features of a hardware profile as the build recipe plans them for another machine
# (orchestrator/runtime/build/recipe.py: X86_FEATURES, _X86_NEEDS and _X86_FLAGS; tests/test_target_stage.py compares
# the plans): the probe's key, the ggml option it switches, the feature it builds on (a feature without it is not
# used) and its /proc/cpuinfo flag (configs/hardware_probe_schema.yml), which a probe file of version 1.x without
# the key still names in CPU_FLAGS_ALL.
X86_FEATURE_TABLE=(
    "SUPPORTS_SSE42 GGML_SSE42 - sse4_2"
    "SUPPORTS_AVX GGML_AVX - avx"
    "SUPPORTS_AVX2 GGML_AVX2 SUPPORTS_AVX avx2"
    "SUPPORTS_BMI2 GGML_BMI2 - bmi2"
    "SUPPORTS_F16C GGML_F16C SUPPORTS_AVX f16c"
    "SUPPORTS_FMA GGML_FMA SUPPORTS_AVX fma"
    "SUPPORTS_AVX512 GGML_AVX512 SUPPORTS_AVX2 avx512f"
    "SUPPORTS_AVX512_VBMI GGML_AVX512_VBMI SUPPORTS_AVX512 avx512vbmi"
    "SUPPORTS_AVX512_VNNI GGML_AVX512_VNNI SUPPORTS_AVX512 avx512_vnni"
    "SUPPORTS_AVX512_BF16 GGML_AVX512_BF16 SUPPORTS_AVX512 avx512_bf16"
    "SUPPORTS_AVX_VNNI GGML_AVX_VNNI SUPPORTS_AVX2 avx_vnni"
    "SUPPORTS_AMX_TILE GGML_AMX_TILE - amx_tile"
    "SUPPORTS_AMX_INT8 GGML_AMX_INT8 SUPPORTS_AMX_TILE amx_int8"
    "SUPPORTS_AMX_BF16 GGML_AMX_BF16 SUPPORTS_AMX_TILE amx_bf16"
)
# The compiler flags ggml adds for each option without GGML_NATIVE, in ggml's order
# (ggml/src/ggml-cpu/CMakeLists.txt:347-410 at the pin).
X86_FLAG_TABLE=(
    "GGML_SSE42 -msse4.2" "GGML_F16C -mf16c" "GGML_FMA -mfma" "GGML_BMI2 -mbmi2" "GGML_AVX -mavx" "GGML_AVX2 -mavx2"
    "GGML_AVX_VNNI -mavxvnni" "GGML_AVX512 -mavx512f -mavx512cd -mavx512vl -mavx512dq -mavx512bw"
    "GGML_AVX512_VBMI -mavx512vbmi" "GGML_AVX512_VNNI -mavx512vnni" "GGML_AVX512_BF16 -mavx512bf16"
    "GGML_AMX_TILE -mamx-tile" "GGML_AMX_INT8 -mamx-int8" "GGML_AMX_BF16 -mamx-bf16"
)
# What GGML_AVX512 compiles for (-mavx512f -mavx512cd -mavx512vl -mavx512dq -mavx512bw: recipe.AVX512_SET). It is used
# only when the profile's CPU flags name all of them: a Xeon Phi (Knights Landing, Knights Mill) has AVX-512 F without
# BW, VL and DQ, and a probe without CPU flags (Windows) cannot tell. Then the plan is the AVX2 plan.
X86_AVX512_SET="avx512f avx512cd avx512vl avx512dq avx512bw"

cpu_flag_list() {  # stdin: CPU flags (separated by spaces or commas) -> the sorted set, comma-separated, lower case
    tr 'A-Z,' 'a-z ' | tr -s ' \t' '\n' | sed '/^$/d' | sort -u | paste -sd, -
}

profile_cpu_flags() {  # CPU_FLAGS_ALL of the profile file as written (the loader drops the spaces of version 1.x)
    awk '/^[[:space:]]*CPU_FLAGS_ALL[[:space:]]*=/ { sub(/^[^=]*=/, ""); print; exit }' "$HARDWARE_CONFIG_FILE" \
        | tr -d '"\r'
}

avx512_missing() {  # CPU_FLAGS (the comma list of cpu_flag_list): the parts of X86_AVX512_SET it does not name
    local part missing=()
    for part in $X86_AVX512_SET; do
        if [[ ",$1," != *",$part,"* ]]; then
            missing+=("$part")
        fi
    done
    echo "${missing[*]}"
}

# The hardware profile describes this build machine itself when it names this machine's CPU: the same system
# (uname -m), the same CPU model and the same CPU flags as /proc/cpuinfo here (the probe's ARCH, CPU_MODEL and
# CPU_FLAGS_ALL; spaces are not compared). Only then is -march=native the profile's CPU. A profile of another
# machine, or one without these facts, gets the explicit features of its probe (explicit_x86_flags).
profile_is_this_machine() {
    local here_model here_flags there_flags there_model
    [ "$(uname -m)" = "${HW_CONFIG[ARCHITECTURE_FULL]}" ] && [ -r /proc/cpuinfo ] || return 1
    here_model="$(awk -F: '/^model name/ { print $2; exit }' /proc/cpuinfo | tr -d ' \t')"
    here_flags="$(awk -F: '/^flags/ { print $2; exit }' /proc/cpuinfo | cpu_flag_list)"
    there_flags="$(profile_cpu_flags | cpu_flag_list)"
    there_model="$(printf '%s' "${HW_CONFIG[CPU_MODEL_NAME]:-}" | tr -d ' \t')"
    [ -n "$here_flags" ] && [ "$here_flags" = "$there_flags" ] \
        && [ -n "$here_model" ] && [ "$here_model" = "$there_model" ]
}

# X86_CFLAGS and X86_CMAKE_FLAGS from the profile's x86 features, as the build recipe plans a build for another
# machine: all 14 ggml options explicit (a feature the probe did not confirm is OFF, never more than it confirmed), a
# feature without the one it builds on is not used, GGML_AVX512 only with every part of X86_AVX512_SET, and the
# compiler flags of the options that are ON on the x86-64 baseline, whatever the image's compiler would choose by
# default.
explicit_x86_flags() {
    local row key option needs token value cpu_flags missing options=() unknown=() used=() unusable=()
    declare -A use
    cpu_flags="$(profile_cpu_flags | cpu_flag_list)"
    for row in "${X86_FEATURE_TABLE[@]}"; do
        read -r key option needs token <<< "$row"
        value="${HW_CONFIG[$key]:-}"
        if [ "$value" != ON ] && [ "$value" != OFF ]; then
            if [ -n "$cpu_flags" ]; then
                value=OFF
                if [[ ",$cpu_flags," == *",$token,"* ]]; then
                    value=ON
                fi
            else
                unknown+=("${key#SUPPORTS_}")
                value=OFF
            fi
        fi
        if [ "$key" = SUPPORTS_AVX512 ] && [ "$value" = ON ]; then
            missing="$(avx512_missing "$cpu_flags")"
            if [ -n "$missing" ]; then
                log_warn "SUPPORTS_AVX512 is ON, but GGML_AVX512 also compiles for ${missing// /, }, which the probe's CPU flags do not name: the AVX2 plan, no AVX-512"
                unusable+=("AVX512:GGML_AVX512 also compiles for ${missing// /, }, which the probe's CPU flags do not name")
                value=OFF
            fi
        fi
        if [ "$value" = ON ] && [ "$needs" != - ] && [ "${use[$needs]:-OFF}" != ON ]; then
            log_warn "$key is ON without $needs in the hardware profile; not used"
            unusable+=("${key#SUPPORTS_}:builds on ${needs#SUPPORTS_}, which the build does not use")
            value=OFF
        fi
        use[$key]="$value"
        if [ "$value" = ON ]; then
            used+=("${key#SUPPORTS_}")
        fi
        options+=("-D$option=$value")
    done
    if [ ${#unknown[@]} -gt 0 ]; then
        log_warn "The hardware profile does not say whether the CPU has ${unknown[*]}: left out (only what the probe confirmed is used)"
    fi
    X86_CMAKE_FLAGS="${options[*]}"
    CPU_FEATURES_USED="$(IFS=,; echo "${used[*]}")"
    CPU_FEATURES_UNUSABLE="$(IFS=';'; echo "${unusable[*]}")"
    local cflags="-march=x86-64"
    for row in "${X86_FLAG_TABLE[@]}"; do
        option="${row%% *}"
        if [[ " $X86_CMAKE_FLAGS " == *" -D$option=ON "* ]]; then
            cflags="$cflags ${row#* }"
        fi
    done
    X86_CFLAGS="$cflags"
}

# The x86 CPU of the plan (the build recipe's plan, decision Q7 of round 25): -march=native for a profile of this build
# machine itself (with GGML_AVX2 and GGML_AVX512 as its probe confirmed them), else explicit_x86_flags. Sets X86_CFLAGS
# (after the other compiler flags, so its -march wins) and X86_CMAKE_FLAGS (after GGML_NATIVE=OFF).
plan_x86_cpu() {
    if profile_is_this_machine; then
        log_info "The hardware profile is of this build machine: -march=native"
        local native=() row key used=()
        for row in "${X86_FEATURE_TABLE[@]}"; do  # -march=native takes every feature this CPU has
            key="${row%% *}"
            if [ "${HW_CONFIG[$key]:-}" = ON ]; then
                used+=("${key#SUPPORTS_}")
            fi
        done
        CPU_FEATURES_USED="$(IFS=,; echo "${used[*]}")"
        CPU_FEATURES_UNUSABLE=""
        X86_CFLAGS="-march=native"
        if [[ "${HW_CONFIG[SUPPORTS_AVX2]:-OFF}" == "ON" ]]; then
            native+=(-DGGML_AVX2=ON)
        fi
        if [[ "${HW_CONFIG[SUPPORTS_AVX512]:-OFF}" == "ON" ]]; then
            if [ -z "$(avx512_missing "$(profile_cpu_flags | cpu_flag_list)")" ]; then
                native+=(-DGGML_AVX512=ON)
            else
                log_warn "SUPPORTS_AVX512 is ON, but this CPU lacks a part of AVX-512 GGML_AVX512 compiles for ($X86_AVX512_SET): no GGML_AVX512"
            fi
        fi
        X86_CMAKE_FLAGS="${native[*]}"
    else
        explicit_x86_flags
        log_info "The hardware profile is of another machine: its CPU features ($X86_CFLAGS), not this machine's (-march=native)"
    fi
}

# ============================================================================
# END OF THE x86_64 CPU
# ============================================================================

# ============================================================================
# THE CPU OF AN aarch64 PROFILE: -march and GGML_CPU_ARM_ARCH from the probe's features
# The same functions in targets/Rockchip and targets/_template (tests/test_target_stage.py compares them, and runs them
# against the build recipe on the same profiles). They read the profile from HW_CONFIG (the SUPPORTS_* keys) and its
# file (HARDWARE_CONFIG_FILE, for CPU_FLAGS_ALL as written), and set ARM_ARCH, ARM_CFLAGS, ARM_CMAKE_FLAGS,
# CPU_FEATURES_USED and CPU_FEATURES_UNUSABLE.
# ============================================================================

# The tags of GGML_CPU_ARM_ARCH as the build recipe plans them (orchestrator/runtime/build/recipe.py: ARM_ARCH_TAGS,
# in ggml's ARCH_TAGS order; the one planner): the probe's key, the -march tag and its /proc/cpuinfo flags
# (configs/hardware_probe_schema.yml), which a probe file of version 1.x without the key still names in CPU_FLAGS_ALL,
# and the key of the tag it builds on (recipe.ARM_NEEDS, - for none): a tag is planned only when its base is.
ARM_TAG_TABLE=(
    "SUPPORTS_DOTPROD dotprod asimddp -"
    "SUPPORTS_FP16_ARITH fp16 fphp,asimdhp -"
    "SUPPORTS_SVE sve sve SUPPORTS_FP16_ARITH"
    "SUPPORTS_I8MM i8mm i8mm SUPPORTS_DOTPROD"
    "SUPPORTS_SVE2 sve2 sve2 SUPPORTS_SVE"
    "SUPPORTS_SME sme sme SUPPORTS_SVE2"
)
# ARM features the board may have that no code of the pinned llama.cpp uses (recipe.ARM_UNUSABLE, from
# ggml_cpu_options.py): the probe's key, its flags, and why.
ARM_UNUSABLE_TABLE=(
    "SUPPORTS_BF16_ARM bf16 the pin has no BF16 kernel for ARM: its ggml-cpu build files neither check nor tag BF16 on ARM"
)
# The oldest compilers that know +sme (recipe.SME_COMPILER_MIN).
SME_GCC_MIN=14
SME_CLANG_MIN=18

arm_feature_value() {  # KEY FLAGS CPU_FLAGS: ON or OFF; UNKNOWN counts as OFF, a 1.x file without the key has its flags
    local value="${HW_CONFIG[$1]:-}" flag
    if [ "$value" = ON ] || [ "$value" = OFF ]; then
        echo "$value"
        return
    fi
    if [ -n "$value" ] || [ -z "$3" ]; then
        echo OFF
        return
    fi
    for flag in ${2//,/ }; do
        if [[ ",$3," != *",$flag,"* ]]; then
            echo OFF
            return
        fi
    done
    echo ON
}

# The C compiler of the plan as "family version" (gcc 12.2.0, clang 18.1.3), empty when this script cannot tell.
plan_c_compiler_version() {  # COMPILER
    local banner version
    command -v "$1" >/dev/null 2>&1 || return 0
    banner="$("$1" --version 2>/dev/null | head -n 1)"
    if [[ "$banner" =~ clang\ version\ ([0-9]+(\.[0-9]+)*) ]]; then
        echo "clang ${BASH_REMATCH[1]}"
        return
    fi
    version="$("$1" -dumpfullversion -dumpversion 2>/dev/null | head -n 1)"
    if [[ "$version" =~ ^[0-9]+(\.[0-9]+)*$ ]] && [[ "$banner" == *gcc* || "$banner" == *GCC* \
            || "$banner" == *"Free Software Foundation"* ]]; then
        echo "gcc $version"
    fi
}

sme_problem() {  # "family version" of the compiler: why it cannot build +sme, empty when it can (recipe.sme_problem)
    local family="${1%% *}" version="${1#* }" major need="GCC $SME_GCC_MIN or Clang $SME_CLANG_MIN" name=GCC minimum
    if [ -z "$1" ] || { [ "$family" != gcc ] && [ "$family" != clang ]; }; then
        echo "compiler too old or not known: +sme needs $need, and the build's compiler version is not known"
        return
    fi
    minimum=$SME_GCC_MIN
    if [ "$family" = clang ]; then
        name=Clang
        minimum=$SME_CLANG_MIN
    fi
    major="${version%%.*}"
    if [ "$major" -lt "$minimum" ]; then
        echo "compiler too old: +sme needs $need, and the build compiles with $name $version"
    fi
}

# GGML_CPU_ARM_ARCH as the build recipe plans it for another machine (recipe.arm_plan): armv8.2-a with the tags of
# the features the profile confirms, armv8-a without any (also for a profile without the keys, the plain defaults);
# +sme only with a compiler that knows it (COMMAND: the plan's C compiler), else SME is named as unusable and the rest is
# built. Never -mcpu: the cores of a board say nothing the probe's features do not (a second planner drifted before).
plan_arm_cpu() {  # [C COMPILER COMMAND]
    local row key tag flags base value cpu_flags problem reason tags="" planned=" " used=() unusable=()
    cpu_flags=""
    if [ "${PROFILE_SOURCE:-}" = profile ]; then
        cpu_flags="$(profile_cpu_flags | cpu_flag_list)"
    fi
    for row in "${ARM_TAG_TABLE[@]}"; do
        read -r key tag flags base <<< "$row"
        value="$(arm_feature_value "$key" "$flags" "$cpu_flags")"
        [ "$value" = ON ] || continue
        if [ "$base" != - ] && [[ "$planned" != *" $base "* ]]; then
            reason="builds on ${base#SUPPORTS_}, which the build does not use"
            unusable+=("${key#SUPPORTS_}:$reason")
            log_warn "The board has ${key#SUPPORTS_}, the build cannot use it: $reason"
            continue
        fi
        if [ "$tag" = sme ]; then
            problem="$(sme_problem "$(plan_c_compiler_version "${1:-}")")"  # asked only for a board with SME
            if [ -n "$problem" ]; then
                unusable+=("${key#SUPPORTS_}:$problem")
                log_warn "The board has SME, the build cannot use it: $problem"
                continue
            fi
        fi
        tags="$tags+$tag"
        planned="$planned$key "
        used+=("${key#SUPPORTS_}")
    done
    for row in "${ARM_UNUSABLE_TABLE[@]}"; do
        read -r key flags reason <<< "$row"
        if [ "$(arm_feature_value "$key" "$flags" "$cpu_flags")" = ON ]; then
            unusable+=("${key#SUPPORTS_}:$reason")
            log_warn "The board has ${key#SUPPORTS_}, the build cannot use it: $reason"
        fi
    done
    if [ -n "$tags" ]; then
        ARM_ARCH="armv8.2-a$tags"
    else
        ARM_ARCH="armv8-a"
    fi
    ARM_CFLAGS="-march=$ARM_ARCH"
    ARM_CMAKE_FLAGS="-DGGML_CPU_ARM_ARCH=$ARM_ARCH"
    CPU_FEATURES_USED="$(IFS=,; echo "${used[*]}")"
    CPU_FEATURES_UNUSABLE="$(IFS=';'; echo "${unusable[*]}")"
    log_info "The CPU of the hardware profile: $ARM_CFLAGS (GGML_CPU_ARM_ARCH, as the build recipe plans it)"
}

# ============================================================================
# END OF THE aarch64 CPU
# ============================================================================

# The module's compiler flags and the build jobs; the compilers CC and CXX of the image.
generate_compiler_flags() {
    local build_jobs name path key
    COMPILER_CONFIG[CFLAGS]='[CPU_FLAGS]'
    COMPILER_CONFIG[CXXFLAGS]='[CPU_FLAGS]'
    # An x86_64 board with its hardware profile: the CPU as the build recipe plans it (plan_x86_cpu: -march=native
    # only for this build machine itself, else the probe's own features), after the module's flags, so its -march wins.
    X86_CFLAGS=""
    X86_CMAKE_FLAGS=""
    ARM_CFLAGS=""
    ARM_CMAKE_FLAGS=""
    CPU_FEATURES_USED=""
    CPU_FEATURES_UNUSABLE=""
    if [ "$PROFILE_SOURCE" = profile ] && [ "$(elf_machine_of "${HW_CONFIG[ARCHITECTURE_FULL]}")" = 62 ]; then
        plan_x86_cpu
        COMPILER_CONFIG[CFLAGS]="${COMPILER_CONFIG[CFLAGS]} $X86_CFLAGS"
        COMPILER_CONFIG[CXXFLAGS]="${COMPILER_CONFIG[CXXFLAGS]} $X86_CFLAGS"
    fi
    # An aarch64 board with its hardware profile: -march and GGML_CPU_ARM_ARCH as the build recipe plans them
    # (plan_arm_cpu, from the probe's features, never from a core name), after the module's flags, so its -march wins.
    if [ "$PROFILE_SOURCE" = profile ] && [ "$(elf_machine_of "${HW_CONFIG[ARCHITECTURE_FULL]}")" = 183 ]; then
        plan_arm_cpu "${CC:-cc}"
        COMPILER_CONFIG[CFLAGS]="${COMPILER_CONFIG[CFLAGS]} $ARM_CFLAGS"
        COMPILER_CONFIG[CXXFLAGS]="${COMPILER_CONFIG[CXXFLAGS]} $ARM_CFLAGS"
    fi
    build_jobs="$(nproc)"
    if [[ "${HW_CONFIG[CPU_CORES]:-}" =~ ^[1-9][0-9]*$ ]] && [[ "${HW_CONFIG[CPU_CORES]}" -lt "$build_jobs" ]]; then
        build_jobs=${HW_CONFIG[CPU_CORES]}
    fi
    COMPILER_CONFIG[BUILD_JOBS]="$build_jobs"
    for key in CC CXX; do
        if [ "$key" = CC ]; then name="${CC:-cc}"; else name="${CXX:-c++}"; fi
        path="$(command -v "$name" || true)"
        [[ "$path" == /* ]] || die "This image has no $name (the $key of the module), which the plan for [IHRE_ARCHITEKTUR] needs; nothing was planned."
        [[ "$path" =~ ^[A-Za-z0-9._/+-]+$ ]] || die "The path of $name has characters a CMake toolchain file cannot hold unquoted; nothing was planned."
        COMPILER_CONFIG[$key]="$path"
    done
}

generate_cmake_toolchain() {
    log "Generating CMake toolchain for [IHRE_ARCHITEKTUR]..."

    # SECURITY CRITICAL:
    # Use 'EOF' (quoted) to prevent shell expansion of variables like [CPU_FLAGS] immediately.
    # This ensures that whatever is in the flags is written literally to the cmake file,
    # and not executed/expanded by the shell during generation.
    cat <<'EOF' > "$CMAKE_TOOLCHAIN"
# Generated CMake Toolchain via LLM Framework
SET(CMAKE_SYSTEM_NAME Linux)
SET(CMAKE_SYSTEM_PROCESSOR [IHRE_ARCHITEKTUR])

# --- COMPILER FLAGS (From Wizard/Template) ---
# Note: These are injected literally by the generator
SET(CMAKE_C_FLAGS "${CMAKE_C_FLAGS} [CPU_FLAGS]")
SET(CMAKE_CXX_FLAGS "${CMAKE_CXX_FLAGS} [CPU_FLAGS]")
EOF
    # The compilers of the image (paths of plain characters only, find in generate_compiler_flags)
    printf '\n# --- COMPILERS (CC and CXX of the image) ---\nSET(CMAKE_C_COMPILER   %s)\nSET(CMAKE_CXX_COMPILER %s)\n' \
        "${COMPILER_CONFIG[CC]}" "${COMPILER_CONFIG[CXX]}" >> "$CMAKE_TOOLCHAIN"
    # The x86 CPU of the plan (plan_x86_cpu: computed words of plain characters, never the module's text)
    if [ -n "$X86_CFLAGS" ]; then
        printf '\n# --- THE x86 CPU OF THE PROFILE (as the build recipe plans it) ---\nSET(CMAKE_C_FLAGS "${CMAKE_C_FLAGS} %s")\nSET(CMAKE_CXX_FLAGS "${CMAKE_CXX_FLAGS} %s")\n' \
            "$X86_CFLAGS" "$X86_CFLAGS" >> "$CMAKE_TOOLCHAIN"
    fi
    # The ARM CPU of the plan (plan_arm_cpu: computed words of plain characters, never the module's text)
    if [ -n "$ARM_CFLAGS" ]; then
        printf '\n# --- THE ARM CPU OF THE PROFILE (as the build recipe plans it) ---\nSET(CMAKE_C_FLAGS "${CMAKE_C_FLAGS} %s")\nSET(CMAKE_CXX_FLAGS "${CMAKE_CXX_FLAGS} %s")\n' \
            "$ARM_CFLAGS" "$ARM_CFLAGS" >> "$CMAKE_TOOLCHAIN"
    fi

    # Dynamic Feature Flags (Based on Probe SUPPORTS_*): CMake options on the cmake command line of the target stage.
    # The CPU options of an x86 or aarch64 profile come from the plan (GGML_NATIVE=OFF and the x86 options or
    # GGML_CPU_ARM_ARCH, after the module's flags).
    CMAKE_OPTIONS='[CMAKE_FLAGS]'
    if [ -n "$X86_CFLAGS" ] || [ -n "$ARM_CFLAGS" ]; then
        if [ -n "$CMAKE_OPTIONS" ]; then
            CMAKE_OPTIONS="$CMAKE_OPTIONS -DGGML_NATIVE=OFF"
        else
            CMAKE_OPTIONS="-DGGML_NATIVE=OFF"
        fi
        if [ -n "$X86_CMAKE_FLAGS$ARM_CMAKE_FLAGS" ]; then
            CMAKE_OPTIONS="$CMAKE_OPTIONS ${X86_CMAKE_FLAGS}${ARM_CMAKE_FLAGS}"
        fi
    fi
    local feature
    for feature in NEON FP16 AVX2 AVX512 CUDA; do
        if [ -n "$X86_CFLAGS" ] && { [ "$feature" = AVX2 ] || [ "$feature" = AVX512 ]; }; then
            continue  # in the x86 plan above
        fi
        if [ -n "$ARM_CFLAGS" ] && { [ "$feature" = NEON ] || [ "$feature" = FP16 ]; }; then
            continue  # NEON is the ARMv8-A baseline, FP16 a tag of GGML_CPU_ARM_ARCH above
        fi
        if [ "${HW_CONFIG[SUPPORTS_$feature]:-OFF}" == "ON" ]; then
            CMAKE_OPTIONS="$CMAKE_OPTIONS -DGGML_$feature=ON"
            log "Auto-Enabled: $feature"
        fi
    done
    log "Toolchain generated at $CMAKE_TOOLCHAIN"
}

# ============================================================================
# VALIDATION (version 1.x: "Professional Validation - compiler tests, syntax checks")
# The same functions in targets/Rockchip and targets/_template (tests/test_target_stage.py compares them). They read
# the plan's compilers and flags from COMPILER_CONFIG (CC, CXX, CFLAGS, CXXFLAGS) and its system from
# HW_CONFIG[ARCHITECTURE_FULL].
# ============================================================================

# The ELF machine number of a program file (62 x86_64, 183 aarch64, 40 32-bit Arm, 3 32-bit x86, 243 RISC-V), empty for a
# file that is no ELF program.
elf_machine() {
    local -a head
    read -r -a head <<< "$(od -An -tu1 -N20 "$1" 2>/dev/null | tr '\n' ' ')"
    [ "${#head[@]}" -eq 20 ] && [ "${head[0]}" = 127 ] && [ "${head[1]}" = 69 ] && [ "${head[2]}" = 76 ] \
        && [ "${head[3]}" = 70 ] || return 0
    if [ "${head[5]}" = 2 ]; then
        echo $(( 256 * head[18] + head[19] ))  # big-endian
    else
        echo $(( head[18] + 256 * head[19] ))
    fi
}

elf_machine_of() {  # SYSTEM: the ELF machine number of its programs, empty when this script does not know it
    case "$1" in
        aarch64|arm64) echo 183 ;;
        x86_64|amd64) echo 62 ;;
        armv7*|armv6*|armv8l|armhf|armel|arm) echo 40 ;;
        x86|i386|i486|i586|i686) echo 3 ;;
        riscv64) echo 243 ;;
        *) echo "" ;;
    esac
}

run_compiler() {  # COMPILER OUTPUT ARGUMENTS...: builds OUTPUT, or stops the stage with the compiler's own words
    local compiler="$1" output="$2"
    shift 2
    if ! "$compiler" "$@" -o "$output" > "$output.log" 2>&1; then
        die "The compiler test failed: $(basename "$compiler") cannot build and link a small program with the flags of the plan (${COMPILER_CONFIG[CFLAGS]}): $(tail -n 8 "$output.log" | tr '\n' ' ')"
    fi
}

# The planned compilers build and link a small C and a small C++ program (with a thread) with the planned flags. A
# program built for this machine itself (-march=native on a machine of the plan's system) is run; any other must be an
# ELF program for the processor of the plan's system.
compiler_test() {
    local dir="$PLAN_DIR/compiler-test" arch="${HW_CONFIG[ARCHITECTURE_FULL]}" want got program
    local -a cflags cxxflags
    read -r -a cflags <<< "${COMPILER_CONFIG[CFLAGS]}"
    read -r -a cxxflags <<< "${COMPILER_CONFIG[CXXFLAGS]}"
    rm -rf "$dir" && mkdir -p "$dir"
    cat > "$dir/test.c" << 'EOF'
#include <stdio.h>
int main(void) { volatile float x = 1.5f; printf("compiler test %d\n", (int)(x * 2.0f)); return 0; }
EOF
    cat > "$dir/test.cpp" << 'EOF'
#include <thread>
#include <vector>
int main() { std::vector<int> v(4, 1); std::thread t([&v] { v[0] = 2; }); t.join(); return v[0] == 2 ? 0 : 1; }
EOF
    run_compiler "${COMPILER_CONFIG[CC]}" "$dir/test-c" "${cflags[@]}" "$dir/test.c"
    run_compiler "${COMPILER_CONFIG[CXX]}" "$dir/test-cxx" "${cxxflags[@]}" "$dir/test.cpp"
    want="$(elf_machine_of "$arch")"
    for program in "$dir/test-c" "$dir/test-cxx"; do
        if [[ " ${cflags[*]} " == *" -march=native "* ]] && [ "$(uname -m)" = "$arch" ]; then
            "$program" > "$program.run" 2>&1 \
                || die "The compiler test failed: a program the plan's compilers built for this machine does not run: $(tail -n 5 "$program.run" | tr '\n' ' ')"
        elif [ -n "$want" ]; then
            got="$(elf_machine "$program")"
            [ -n "$got" ] && [ "$got" = "$want" ] \
                || die "The compiler test failed: the plan's compilers do not build programs for the $arch system of the plan (ELF machine ${got:-none}, expected $want). The image needs a cross compiler for it (a module names it with CC and CXX in its Dockerfile)."
        else
            log_warn "The compiler test built and linked the programs; for a $arch system it cannot tell their processor."
        fi
    done
    rm -rf "$dir"
    log_success "Compiler test passed: C and C++ programs for $arch, built and linked with the flags of the plan"
}

# CMake reads the toolchain file as the target stage's cmake will (script mode stops at a syntax error), and the file
# names the system and the compilers.
check_toolchain_file() {
    local file="$1" key
    if command -v cmake > /dev/null 2>&1; then
        command cmake -P "$file" > "$file.log" 2>&1 \
            || die "The CMake toolchain file is not valid: $(tail -n 5 "$file.log" | tr '\n' ' ')"
        rm -f "$file.log"
    fi
    for key in CMAKE_SYSTEM_NAME CMAKE_SYSTEM_PROCESSOR CMAKE_C_COMPILER CMAKE_CXX_COMPILER; do
        grep -Eq "^SET\\(${key}[[:space:]]" "$file" || die "The CMake toolchain file sets no $key."
    done
}

# A plan file is a valid shell script, and a clean shell that reads it has every name given after it.
check_plan_file() {  # FILE NAME...
    local file="$1" missing
    shift
    bash -n "$file" 2> "$file.log" || die "The build plan is not a valid shell script: $(tail -n 3 "$file.log" | tr '\n' ' ')"
    rm -f "$file.log"
    # shellcheck disable=SC2016  # expanded by the clean shell
    missing="$(env -i bash --noprofile --norc -c 'set -u; source "$1"; shift; for n in "$@"; do [ -n "${!n+set}" ] || printf "%s " "$n"; done' _ "$file" "$@" 2>&1)" \
        || die "The build plan cannot be read: $missing"
    [ -z "$missing" ] || die "The build plan does not set: ${missing% }."
}

# ============================================================================
# END OF VALIDATION
# ============================================================================

# The names the later stages read from the build plan (and, for a package, from its board part).
PLAN_NAMES=(FORMAT BOARD QUANT_TYPE QUANT JOB MODEL_SOURCE INPUT_FORMAT MODEL_NAME OUTPUT_DIR IMATRIX_DIR SCRATCH_DIR
            LLAMA_BASE CONVERT_SCRIPT QUANTIZE_BIN IMATRIX_BIN BOARD_PACKAGE)
BOARD_PLAN_NAMES=(BOARD_PACKAGE PROFILE_SOURCE HARDWARE_PROFILE TARGET_CPU PROFILE_ARCH CFLAGS CXXFLAGS CMAKE_FLAGS
                  CMAKE_TOOLCHAIN_FILE BUILD_JOBS)

# The board: the toolchain and the flags with the hardware profile (profile) or with the plain defaults of this
# module (defaults: a package without a profile), checked before anything uses them.
plan_board() {  # profile | defaults
    if [ "$1" = profile ]; then
        load_hardware_config
    else
        load_plain_defaults
    fi
    generate_compiler_flags
    generate_cmake_toolchain
    check_toolchain_file "$CMAKE_TOOLCHAIN"
    compiler_test
}

# --- The build plan -------------------------------------------------------------------------------------------------

plan_line() { printf '%s=%q\n' "$1" "$2"; }

# The board's part of the plan (in build_config.sh, or in the package plan of the target stage), from plan_board.
board_plan_lines() {
    echo "# Hardware profile of the board (for the package of llama-cli and llama-server, target stage)"
    plan_line BOARD_PACKAGE 1
    # profile: the board's hardware profile; defaults: none was given, the plain defaults of this module
    plan_line PROFILE_SOURCE "$PROFILE_SOURCE"
    if [ "$PROFILE_SOURCE" = profile ]; then
        plan_line HARDWARE_PROFILE "$HARDWARE_CONFIG_FILE"
    else
        plan_line HARDWARE_PROFILE ""
    fi
    plan_line TARGET_CPU "${HW_CONFIG[CPU_MODEL]:-}"
    plan_line PROFILE_ARCH '[IHRE_ARCHITEKTUR]'
    plan_line CFLAGS "${COMPILER_CONFIG[CFLAGS]}"
    plan_line CXXFLAGS "${COMPILER_CONFIG[CXXFLAGS]}"
    plan_line CMAKE_TOOLCHAIN_FILE "$CMAKE_TOOLCHAIN"
    plan_line CMAKE_FLAGS "$CMAKE_OPTIONS"
    plan_line BUILD_JOBS "${COMPILER_CONFIG[BUILD_JOBS]}"
    # the probe's CPU features the plan uses, and those the board has that it cannot use ("FEATURE:reason;...")
    plan_line CPU_FEATURES_USED "${CPU_FEATURES_USED:-}"
    plan_line CPU_FEATURES_UNUSABLE "${CPU_FEATURES_UNUSABLE:-}"
}

generate_build_config() {
    {
        echo "# Build plan, written by config_module.sh; convert_module.sh and target_module.sh read it."
        plan_line FORMAT "$FORMAT"
        plan_line BOARD "$BOARD"
        plan_line QUANT_TYPE "$QUANT_TYPE"
        # The name the dispatcher of the template gave it too (QUANT="$QUANT_TYPE"): module definitions use both.
        plan_line QUANT "$QUANT_TYPE"
        plan_line JOB "$JOB"
        plan_line MODEL_SOURCE "$MODEL_SOURCE"
        plan_line INPUT_FORMAT "$INPUT_FORMAT"
        plan_line MODEL_NAME "$MODEL_NAME"
        plan_line OUTPUT_DIR "$OUTPUT_DIR"
        plan_line IMATRIX_DIR "$IMATRIX_DIR"
        plan_line SCRATCH_DIR "$SCRATCH_DIR"
        plan_line LLAMA_BASE "$LLAMA_BASE"
        plan_line CONVERT_SCRIPT "$CONVERT_SCRIPT"
        plan_line QUANTIZE_BIN "$QUANTIZE_BIN"
        plan_line IMATRIX_BIN "$IMATRIX_BIN"
        if [ -f "$CMAKE_TOOLCHAIN" ]; then
            board_plan_lines
        else
            plan_line BOARD_PACKAGE 0
        fi
    } > "$BUILD_PLAN.tmp"
    check_plan_file "$BUILD_PLAN.tmp" "${PLAN_NAMES[@]}"
    if [ -f "$CMAKE_TOOLCHAIN" ]; then
        check_plan_file "$BUILD_PLAN.tmp" "${BOARD_PLAN_NAMES[@]}"
    fi
    mv -f "$BUILD_PLAN.tmp" "$BUILD_PLAN"
    stage_output "$BUILD_PLAN"
    if [ -f "$CMAKE_TOOLCHAIN" ]; then
        stage_output "$CMAKE_TOOLCHAIN"
    fi
}

main() {
    plan_request
    HARDWARE_CONFIG_FILE="${HARDWARE_CONFIG_FILE:-$BUILD_CACHE_DIR/target_hardware_config.txt}"
    rm -f "$CMAKE_TOOLCHAIN"
    if [ -f "$HARDWARE_CONFIG_FILE" ]; then
        plan_board profile
    fi
    generate_build_config
}

if [[ "${BASH_SOURCE[0]}" == "${0}" ]]; then
    # Started by hand: the build up to this stage, through the framework's stage runner (the runtime layer's
    # runner.sh: /llmcf in a build container, the repository's copy in a checkout).
    if [ -z "${STAGE_RUNNER:-}" ]; then
        layer="${LLMCF_LAYER:-/llmcf}"
        [ -f "$layer/runner.sh" ] || layer="$(dirname "${BASH_SOURCE[0]}")/../../../orchestrator/runtime_layer"
        LLMCF_MODULES_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)" exec sh "$layer/runner.sh" --to config "$@"
    fi
    main "$@"
fi
